window.__APP_PARTS=window.__APP_PARTS||[];window.__APP_PARTS[1]="\",\"level_waves\":\"data:image/webp;base64,\",\"rewards\":\"data:image/webp;base64,\"},\"documents\":[{\"image\":\"wbs_plan\",\"category\":\"일정·업무 관리 · WBS\",\"title\":\"기획부터 구현까지 업무를 단계별로 관리\",\"detail\":\"기획서·전투 시스템·보상 테이블·WBS 작성과 개발 항목을 일정, 완료 여부, 담당자와 함께 정리했습니다. WBS에는 완료뿐 아니라 튜토리얼 스토리보드의 보류 상태도 남아 있습니다.\",\"source\":\"개인프로젝트 WBS.xlsx · WBS 시트 A3:G23\",\"link\":\"https://docs.google.com/spreadsheets/d/1v0ppYgPnlv_ISSwXf4SlckajI0BUEQag/edit\"},{\"image\":\"wbs_schedule\",\"category\":\"일정 계획 · WBS\",\"title\":\"시작일·완료 예정일과 책임 범위 확인\",\"detail\":\"일정표에는 작업별 시작일과 예상 작업일, 담당자가 기록되어 있습니다. 이는 수행 과정의 관리 기록이며 모든 작업의 최종 품질 검증이 끝났다는 의미는 아닙니다.\",\"source\":\"개인프로젝트 WBS.xlsx · WBS 시트 A3:Q17\",\"link\":\"https://docs.google.com/spreadsheets/d/1v0ppYgPnlv_ISSwXf4SlckajI0BUEQag/edit\"},{\"image\":\"level_concept\",\"category\":\"레벨 디자인 · 기획서 원문\",\"title\":\"스테이지 콘셉트 변경의 기준을 문서화\",\"detail\":\"다양한 환경·몬스터 테마를 초원/숲과 고양이 몬스터로 통일하고, 차별화 기준을 배경이 아닌 역할·행동 패턴·색상·소품으로 변경했습니다. 5스테이지·3웨이브 구조와 의도를 문서로 명시했습니다.\",\"source\":\"전투 / 레벨 디자인 기획서 · 1쪽 (개정본)\",\"link\":\"https://docs.google.com/document/d/1yIKQ6oUNLq9Ybw01ebAFS7x7EEAH-ihw/edit\"},{\"image\":\"level_waves\",\"category\":\"전투 구성 · 스테이지 설계\",\"title\":\"웨이브별 적 조합과 목표 경험 설정\",\"detail\":\"스테이지에 따른 고양이 역할 조합, 웨이브별 개체수와 목표 시간, 보스 패턴을 정의한 문서입니다. 개별 조합 수치는 설계 기준이며 실제 테스트 수치와 구별됩니다.\",\"source\":\"전투 / 레벨 디자인 기획서 · 3쪽 (개정본)\",\"link\":\"https://docs.google.com/document/d/1yIKQ6oUNLq9Ybw01ebAFS7x7EEAH-ihw/edit\"},{\"image\":\"rewards\",\"category\":\"데이터 테이블 · 보상 시스템\",\"title\":\"보상 카드의 규칙과 수치 정리\",\"detail\":\"보상 카드의 ID·등급·효과 설명·중첩 가능 여부·배타 그룹을 행 단위로 관리했습니다. 이 파일의 관리 메모에는 총 31장으로 기록되어 있고, 개발일지에 언급되는 카드 수와 차이가 있어 최종 적용 버전은 별도 확인이 필요합니다.\",\"source\":\"reward_data_table_completed.xlsx · 시트1 B2:G15\",\"link\":\"https://docs.google.com/spreadsheets/d/1KpONoEKSe9oCQr8FfDvdlTzmFv0tqLaD/edit\"}],\"deepEvidence\":[{\"title\":\"프로젝트 계획·일정 관리\",\"description\":\"WBS에서 기획·개발·테스트 업무를 나누고 각 작업의 담당, 상태, 예정 일정을 관리했습니다.\",\"pages\":[{\"file\":\"wbs_업무진행_원본.webp\",\"caption\":\"WBS 업무 목록 · 실제 진행 상태 기록\",\"source\":\"개인프로젝트 WBS.xlsx\",\"src\":\"data:image/webp;base64,\"},{\"file\":\"wbs_일정_원본.webp\",\"caption\":\"WBS 일정 계획 · 실제 작업 일정표\",\"source\":\"개인프로젝트 WBS.xlsx\",\"src\":\"data:image/webp;base64,\"}],\"link\":\"https://docs.google.com/spreadsheets/d/1v0ppYgPnlv_ISSwXf4SlckajI0BUEQag/edit\"},{\"title\":\"레벨 디자인 · 단계별 학습과 난이도 설계\",\"description\":\"각 스테이지에 고양이 몬스터의 역할, 개체수, 웨이브별 목표 시간과 보스 패턴을 정의했습니다. 단일 초원·숲 테마 안에서 공격 패턴의 조합으로 체감 난도를 구분했습니다.\",\"pages\":[{\"file\":\"레벨설계_전체_01쪽.webp\",\"caption\":\"레벨 디자인 기획서 원본 · 1쪽\",\"source\":\"전투/레벨 디자인 기획서\",\"src\":\"data:image/webp;base64,\"},{\"file\":\"레벨설계_전체_02쪽.webp\",\"caption\":\"레벨 디자인 기획서 원본 · 2쪽\",\"source\":\"전투/레벨 디자인 기획서\",\"src\":\"data:image/webp;base64,";